-- =====================================================================
-- WLF Electrical Solution v2.5.5
--  * Supplier Claim: optional claim reference number (e.g. Arkel ST...),
--    entered when "Supplier Accepted Claim" is saved and editable until the
--    goods are Received; Super Admin can undo a Received (back to Pending).
--  * Troubleshooting: new controller MOTCUBE with "Error Solution"
--    (61 codes, English + Bangla) and the sub option "Permanent Error
--    Clearing". Super Admin can edit, add and delete like MOT / NICE3000+.
-- Run in Supabase > SQL Editor after v2.5.4 (UPDATE_V254.sql). Safe to run
-- twice (your edits to MOTCUBE entries are never overwritten).
-- Back up first. If an RLS warning appears, choose "Run without RLS".
-- =====================================================================
begin;

do $pre$ begin
  if to_regprocedure('wlf_private.rpc_before_v254(text,jsonb)') is null then
    raise exception 'STOP: apply UPDATE_V254.sql (v2.5.4) first. Nothing was changed.';
  end if;
end $pre$;

-- ---------------------------------------------------------------- supplier claim columns
alter table wlf_private.damage_demands
  add column if not exists claim_ref text,
  add column if not exists sc_undo_at timestamptz,
  add column if not exists sc_undo_name text;

create or replace function wlf_private.damage_demand_row(d wlf_private.damage_demands)
returns jsonb language sql stable set search_path='' as $$
  select jsonb_build_object(
    'id',d.request_id,'number',d.demand_no,'reference','DD-'||d.demand_no,
    'category',d.category,'requestReference',d.request_reference,'requesterName',d.requester_name,
    'project',d.project,'lift',d.lift_id,'controllers',d.controllers,'problemCategories',d.problem_categories,
    'itemName',d.item_name,'itemCode',d.item_code,'itemSpec',d.item_spec,'quantity',d.quantity,
    'status',case when d.received_at is null then 'Pending' else 'Received' end,
    'createdAt',d.created_at,'receivedAt',d.received_at,'receivedBy',d.received_name,
    'confirmedBy',d.confirmed_name,'durationMinutes',d.duration_minutes,
    'supplierClaim',d.claim_at is not null,
    'supplierConfirmed',d.confirm_at is not null,
    'supplier',jsonb_build_object('name',coalesce(d.claim_supplier,''),'date',d.claim_date,'note',coalesce(d.claim_note,''),
      'reference',coalesce(d.claim_ref,''),
      'claimAt',d.claim_at,'claimBy',d.claim_name,'confirmAt',d.confirm_at,'confirmBy',d.confirm_name,
      'receivedAt',d.sc_received_at,'receivedBy',d.sc_received_name,
      'undoAt',d.sc_undo_at,'undoBy',d.sc_undo_name,
      'status',case when d.confirm_at is null then null when d.sc_received_at is null then 'Pending' else 'Received' end)
  )
$$;

-- ---------------------------------------------------------------- MOTCUBE: permission tick in User Management
do $o$ begin
  if to_regprocedure('wlf_private.options_before_v255()') is null then
    alter function wlf_private.options() rename to options_before_v255;
  end if;
end $o$;
create or replace function wlf_private.options() returns jsonb
language sql stable security definer set search_path='' as $$
  select wlf_private.options_before_v255() || '[{"id":"group-motcube-error","controller":"MOTCUBE","kind":"error"}]'::jsonb
$$;

-- ---------------------------------------------------------------- RPC layer
do $layer$ begin
  if to_regprocedure('wlf_private.rpc_before_v255(text,jsonb)') is null then
    alter function wlf_private.rpc(text,jsonb) rename to rpc_before_v255;
  end if;
end $layer$;

create or replace function wlf_private.rpc(a text, args jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare
  p jsonb := coalesce(args->0,'{}');
  u public.wlf_profiles;
  d wlf_private.damage_demands;
  tr public.wlf_troubleshooting;
  ref text;
  st text;
  act text;
  rev integer;
  v jsonb;
  opt_key text;
  result jsonb;
begin
  u := wlf_private.me();
  if u.id is null or u.status is distinct from 'Approved' then
    raise exception 'SESSION_EXPIRED: Account is pending approval or inactive';
  end if;

  -- ------------------------------------------------ Supplier Claim
  if a='confirmSupplierClaim' then
    if not (u.role='Super Admin' or 'supplier:confirm'=any(u.permissions)) then
      raise exception 'You do not have Supplier Confirmed access.';
    end if;
    ref := nullif(btrim(coalesce(p->>'reference','')),'');
    if length(coalesce(ref,''))>60 then raise exception 'Claim reference is too long (60 characters at most).'; end if;
    select * into d from wlf_private.damage_demands where request_id=nullif(p->>'id','')::uuid for update;
    if not found then raise exception 'Damage demand not found.'; end if;
    if d.claim_at is null then raise exception 'Mark "Claim Sent to Supplier" first.'; end if;
    if d.confirm_at is not null then raise exception 'Supplier Confirmed is already Yes. Refresh the list.'; end if;
    update wlf_private.damage_demands set confirm_at=now(),confirm_by=u.id,confirm_name=u.name,claim_ref=ref
      where request_id=d.request_id returning * into d;
    return wlf_private.damage_demand_detail(d);

  elsif a='saveSupplierReference' then
    if not (u.role='Super Admin' or 'supplier:confirm'=any(u.permissions)) then
      raise exception 'You do not have Supplier Confirmed access.';
    end if;
    ref := nullif(btrim(coalesce(p->>'reference','')),'');
    if length(coalesce(ref,''))>60 then raise exception 'Claim reference is too long (60 characters at most).'; end if;
    select * into d from wlf_private.damage_demands where request_id=nullif(p->>'id','')::uuid for update;
    if not found then raise exception 'Damage demand not found.'; end if;
    if d.confirm_at is null then raise exception 'Supplier Confirmed is not Yes for this demand.'; end if;
    if d.sc_received_at is not null then raise exception 'Goods are already Received. The reference can no longer be changed.'; end if;
    update wlf_private.damage_demands set claim_ref=ref where request_id=d.request_id returning * into d;
    return wlf_private.damage_demand_detail(d);

  elsif a='cancelSupplierClaim' then
    -- Super Admin only: undo a wrong Yes. Goods must not be Received (undo that first).
    if u.role<>'Super Admin' then raise exception 'Only the Super Admin can cancel a Supplier Claim.'; end if;
    st := coalesce(p->>'step','');
    if st not in ('claim','confirm') then raise exception 'Choose which step to cancel.'; end if;
    select * into d from wlf_private.damage_demands where request_id=nullif(p->>'id','')::uuid for update;
    if not found then raise exception 'Damage demand not found.'; end if;
    if d.sc_received_at is not null then raise exception 'Goods are already Received. Use "Undo Received" first.'; end if;
    if st='confirm' then
      update wlf_private.damage_demands set confirm_at=null,confirm_by=null,confirm_name=null,claim_ref=null
        where request_id=d.request_id returning * into d;
    else
      update wlf_private.damage_demands set claim_at=null,claim_by=null,claim_name=null,claim_supplier=null,claim_date=null,claim_note=null,
          confirm_at=null,confirm_by=null,confirm_name=null,claim_ref=null
        where request_id=d.request_id returning * into d;
    end if;
    return wlf_private.damage_demand_detail(d);

  elsif a='undoSupplierReceive' then
    if u.role<>'Super Admin' then raise exception 'Only the Super Admin can undo Received.'; end if;
    select * into d from wlf_private.damage_demands where request_id=nullif(p->>'id','')::uuid for update;
    if not found then raise exception 'Damage demand not found.'; end if;
    if d.sc_received_at is null then raise exception 'This Supplier Claim is not Received.'; end if;
    update wlf_private.damage_demands set sc_received_at=null,sc_received_by=null,sc_received_name=null,
        sc_undo_at=now(),sc_undo_name=u.name
      where request_id=d.request_id returning * into d;
    return wlf_private.damage_demand_detail(d);

  -- ------------------------------------------------ Troubleshooting: MOTCUBE
  elsif a='saveTroubleshootingEntry' and (p->>'controller')='MOTCUBE' then
    if u.role<>'Super Admin' then raise exception 'Permission denied'; end if;
    if coalesce(p->>'id','')!~'^[-a-zA-Z0-9]{6,100}$' or length(p::text)>40000 then raise exception 'Invalid troubleshooting entry'; end if;
    if p->>'kind'='procedure' then
      if coalesce(btrim(p->>'category'),'')='' then raise exception 'Subcategory name required'; end if;
      opt_key := 'procedure:'||lower(regexp_replace(p->>'category','[^a-zA-Z0-9ঀ-৿]+','','g'));
    else
      if coalesce(p->>'code','')!~'^H[0-9]+$' or coalesce(p->>'description','')='' then raise exception 'Code and description required'; end if;
      opt_key := p->>'code';
    end if;
    select * into tr from public.wlf_troubleshooting where id=p->>'id' for update;
    if found and not tr.deleted and coalesce(p->>'mutationId','')<>'' and tr.content->>'mutationId'=p->>'mutationId'
       and (tr.content-'revision'-'updatedAt'-'updatedBy')=(p-'revision'-'updatedAt'-'updatedBy') then
      return tr.content;
    end if;
    if found and (tr.deleted or tr.revision<>coalesce((p->>'revision')::integer,0)) then raise exception 'TB_CONFLICT: Entry changed'; end if;
    rev := coalesce(tr.revision,0)+1;
    v := p||jsonb_build_object('revision',rev,'updatedAt',now(),'updatedBy',u.email);
    insert into public.wlf_troubleshooting(id,controller,option_key,content,revision)
      values(p->>'id','MOTCUBE',opt_key,v,rev)
      on conflict(id) do update set content=excluded.content,revision=excluded.revision,controller=excluded.controller,option_key=excluded.option_key;
    return v;

  elsif a='logAction' and coalesce(args->>0,'') ~ '^Troubleshooting / MOTCUBE / .{1,180}$' then
    act := left(args->>0,220);
    if not exists(select 1 from public.wlf_troubleshooting t
        where not t.deleted and t.controller='MOTCUBE'
          and (case when t.content->>'kind'='procedure' then t.content->>'category' else 'Error Solution' end)=split_part(act,' / ',3)
          and (u.role<>'User' or (case when t.content->>'kind'='procedure' then 'tb:option:'||t.id else 'tb:MOTCUBE:error' end)=any(u.permissions))) then
      raise exception 'Permission denied';
    end if;
    insert into public.wlf_usage(actor,action,details) values(u.id,act,left(coalesce(args->>1,''),300));
    return 'true'::jsonb;
  end if;

  result := wlf_private.rpc_before_v255(a,args);
  if a in ('getSession','getAppContext') and jsonb_typeof(result)='object' then
    result := result||jsonb_build_object('build','2.5.5','motcube',true);
  end if;
  return result;
end
$$;

revoke all on function wlf_private.rpc_before_v255(text,jsonb) from public, anon, authenticated;
revoke all on function wlf_private.options_before_v255() from public, anon, authenticated;
revoke all on function wlf_private.rpc(text,jsonb) from public, anon;
grant execute on function wlf_private.rpc(text,jsonb) to authenticated;

-- ---------------------------------------------------------------- MOTCUBE data (English + Bangla)
-- Inserted only when missing: anything you edit later is kept if this file is run again.
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h1','MOTCUBE','H1',$j${"id": "motcube-h1", "controller": "MOTCUBE", "kind": "error", "code": "H1", "description": "Fail to lock door. 140 signal is missed", "conditions": "After the door close command, signal 140 is still OFF within the time set in parameter \"7.9: DELAY BEFORE DOOR CLOSING RETRY\".", "solution": ["Increase the time value if it is set too low.", "Check the safety circuit."], "subcodes": [], "fields": [], "category": "", "parameters": ["7.9: DELAY BEFORE DOOR CLOSING RETRY"], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Door lock হয়নি। 140 signal পাওয়া যায়নি", "conditions": "Door close command দেওয়ার পর \"7.9: DELAY BEFORE DOOR CLOSING RETRY\" parameter-এ দেওয়া সময়ের মধ্যে 140 signal OFF থেকে গেলে এই error আসে।", "solution": ["সময়ের মান খুব কম দেওয়া থাকলে সেটা বাড়ান।", "Safety circuit check করুন।"], "src": {"d": "cd90b555", "c": "95f99043", "s": "102e50ec"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h2','MOTCUBE','H2',$j${"id": "motcube-h2", "controller": "MOTCUBE", "kind": "error", "code": "H2", "description": "Floor to floor max travel time elapsed", "conditions": "The car could not reach a new floor within the time set in parameter \"2.8: MAXIMUM TRAVEL TIME BETWEEN FLOORS\".", "solution": ["Increase the time value if it is set too low.", "If the value is already enough, check the ML1-ML2 signals while the car is moving."], "subcodes": [], "fields": [], "category": "", "parameters": ["2.8: MAXIMUM TRAVEL TIME BETWEEN FLOORS"], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Floor to floor সর্বোচ্চ travel time পার হয়ে গেছে", "conditions": "\"2.8: MAXIMUM TRAVEL TIME BETWEEN FLOORS\" parameter-এ দেওয়া সময়ের মধ্যে car নতুন floor-এ পৌঁছাতে না পারলে এই error আসে।", "solution": ["সময়ের মান কম দেওয়া থাকলে বাড়ান।", "মান যথেষ্ট থাকলে car চলার সময় ML1-ML2 signal check করুন।"], "src": {"d": "642244cf", "c": "c5ad5139", "s": "9477965f"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h3','MOTCUBE','H3',$j${"id": "motcube-h3", "controller": "MOTCUBE", "kind": "error", "code": "H3", "description": "Door is not closed for a long time", "conditions": "The door could not be closed (140 signal is OFF) within the time set in parameter \"7.7: DOOR OPEN ERROR\". The system goes to out of service.", "solution": ["Set the time long enough so that the error is not raised unnecessarily.", "If the error still appears although the doors are closed, check the door contacts and the 140 signal on the controller board."], "subcodes": [], "fields": [], "category": "", "parameters": ["7.7: DOOR OPEN ERROR"], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Door অনেকক্ষণ ধরে close হচ্ছে না", "conditions": "\"7.7: DOOR OPEN ERROR\" parameter-এ দেওয়া সময়ের মধ্যে door close না হলে (140 signal OFF) এই error আসে এবং system out of service-এ চলে যায়।", "solution": ["অপ্রয়োজনে error না আসার জন্য সময়ের মান যথেষ্ট রাখুন।", "Door বন্ধ থাকার পরও error আসলে door contacts এবং controller board-এর 140 signal check করুন।"], "src": {"d": "9c179e61", "c": "fab86a9e", "s": "17f4e246"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h4','MOTCUBE','H4',$j${"id": "motcube-h4", "controller": "MOTCUBE", "kind": "error", "code": "H4", "description": "Car can't hold. Please check motor parameters", "conditions": "During auto tuning, the motor turned more than a certain value.", "solution": ["Check the motor parameters."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Car hold করতে পারছে না। Motor parameters check করুন", "conditions": "Auto tuning-এর সময় motor নির্দিষ্ট মানের বেশি ঘুরে গেলে এই error আসে।", "solution": ["Motor parameters check করুন।"], "src": {"d": "7c7ec08e", "c": "1c2a3cb8", "s": "3f0c7e0d"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h5','MOTCUBE','H5',$j${"id": "motcube-h5", "controller": "MOTCUBE", "kind": "error", "code": "H5", "description": "Both limit switches UP & DOWN are open", "conditions": "Both limit switches are in OFF position at the same time. Under normal circumstances one of them can be OFF, but at least one of them must be ON. According to the manual, if the car is at the bottom floor 818 is ON, and if the car is at the top floor 817 is ON.", "solution": ["Check the magnetic switches, the magnets and their order."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "UP ও DOWN দুটি limit switch-ই open", "conditions": "দুটি limit switch একই সময়ে OFF position-এ থাকলে এই error আসে। স্বাভাবিক অবস্থায় একটি OFF থাকতে পারে, কিন্তু অন্তত একটি ON থাকতে হবে। Manual অনুযায়ী car bottom floor-এ থাকলে 818 ON এবং top floor-এ থাকলে 817 ON থাকে।", "solution": ["Magnetic switch, magnet এবং তাদের order (বসানোর ক্রম) check করুন।"], "src": {"d": "ffad802a", "c": "bef12e08", "s": "e3a19741"}}, "sourceNote": "Source manual inconsistency: H5 says 818 is ON at the bottom floor and 817 at the top floor, while H6/H7 say 818 is the top-floor and 817 the bottom-floor magnet. Verify on site before relying on H5 wording. / Source manual-এ অসঙ্গতি: H5-এ বলা আছে bottom floor-এ 818 ও top floor-এ 817 ON থাকে, কিন্তু H6/H7 অনুযায়ী 818 top floor ও 817 bottom floor-এর magnet। H5-এর বক্তব্য site-এ যাচাই করে নিন।"}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h6','MOTCUBE','H6',$j${"id": "motcube-h6", "controller": "MOTCUBE", "kind": "error", "code": "H6", "description": "Top limit switch cuts off while running down", "conditions": "818 magnets are used at the top floor, and the 818 signal can turn OFF only while going in the up direction. If it turns OFF while going down, this error is raised.", "solution": ["Make sure the red and white side of the round magnets are put in the correct order."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Down চলার সময় top limit switch cut off হয়েছে", "conditions": "Top floor-এ 818 magnet ব্যবহার হয় এবং 818 signal শুধু up direction-এ যাওয়ার সময় OFF হতে পারে। Down যাওয়ার সময় OFF হলে এই error আসে।", "solution": ["Round magnet-এর red ও white side সঠিক order-এ বসানো আছে কিনা নিশ্চিত করুন।"], "src": {"d": "964d72d7", "c": "85c1eed5", "s": "75ae33d1"}}, "sourceNote": "Source manual uses 'red and white side' of the round magnets in H6/H7 but 'red and black side' in the installation section; the installation section (red/black) is likely correct. / H6/H7-এ round magnet-এর 'red and white side' লেখা আছে, কিন্তু installation section-এ 'red and black side'; সম্ভবত installation section (red/black) সঠিক।"}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h7','MOTCUBE','H7',$j${"id": "motcube-h7", "controller": "MOTCUBE", "kind": "error", "code": "H7", "description": "Bottom limit switch cuts off while running up", "conditions": "817 magnets are used at the bottom floor, and the 817 signal can turn OFF only while going in the down direction. If it turns OFF while going up, this error is raised.", "solution": ["Make sure the red and white side of the round magnets are put in the correct order."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Up চলার সময় bottom limit switch cut off হয়েছে", "conditions": "Bottom floor-এ 817 magnet ব্যবহার হয় এবং 817 signal শুধু down direction-এ যাওয়ার সময় OFF হতে পারে। Up যাওয়ার সময় OFF হলে এই error আসে।", "solution": ["Round magnet-এর red ও white side সঠিক order-এ বসানো আছে কিনা নিশ্চিত করুন।"], "src": {"d": "5bd4866e", "c": "cccd5cc5", "s": "75ae33d1"}}, "sourceNote": "Source manual uses 'red and white side' of the round magnets in H6/H7 but 'red and black side' in the installation section; the installation section (red/black) is likely correct. / H6/H7-এ round magnet-এর 'red and white side' লেখা আছে, কিন্তু installation section-এ 'red and black side'; সম্ভবত installation section (red/black) সঠিক।"}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h8','MOTCUBE','H8',$j${"id": "motcube-h8", "controller": "MOTCUBE", "kind": "error", "code": "H8", "description": "Low DC bus voltage", "conditions": "The mains supply is lower than the working voltage.", "solution": ["Check the mains supply at the L1, L2, L3 inputs."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "DC bus voltage কম", "conditions": "Mains supply working voltage-এর চেয়ে কম হলে এই error আসে।", "solution": ["L1, L2, L3 input-এ mains supply check করুন।"], "src": {"d": "77aaf3a4", "c": "29164c0b", "s": "383c8b3a"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h9','MOTCUBE','H9',$j${"id": "motcube-h9", "controller": "MOTCUBE", "kind": "error", "code": "H9", "description": "High DC bus voltage", "conditions": "The DC-bus voltage is higher than the limit voltage. This happens when the mains supply rises above a certain value.", "solution": ["Check the mains supply at the L1, L2, L3 inputs. Phase to phase voltage should not be more than 440V.", "Check the brake resistor connections."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "DC bus voltage বেশি", "conditions": "DC-bus voltage limit voltage-এর চেয়ে বেশি হলে এই error আসে। Mains supply একটি নির্দিষ্ট মানের উপরে উঠলে এটি হয়।", "solution": ["L1, L2, L3 input-এ mains supply check করুন। Phase to phase voltage 440V-এর বেশি হওয়া উচিত নয়।", "Brake resistor-এর connection check করুন।"], "src": {"d": "8e57fa70", "c": "4f848cf0", "s": "6991ddbe"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h10','MOTCUBE','H10',$j${"id": "motcube-h10", "controller": "MOTCUBE", "kind": "error", "code": "H10", "description": "KRC check back error", "conditions": "The brake position is monitored over the KRC input. The KRC signal does not behave as expected.", "solution": ["Check the KRC signal on MOTCUBE. While the car is standing still it should be 24V. When the car starts moving, the signal should be cut."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "KRC check back error", "conditions": "Brake-এর position KRC input দিয়ে monitor করা হয়। KRC signal প্রত্যাশিত অবস্থায় না থাকলে এই error আসে।", "solution": ["MOTCUBE-এর KRC signal check করুন। Car দাঁড়িয়ে থাকার সময় এটি 24V থাকা উচিত। Car চলা শুরু করলে signal cut হওয়া উচিত।"], "src": {"d": "1ee788c4", "c": "827afafe", "s": "e48c8172"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h11','MOTCUBE','H11',$j${"id": "motcube-h11", "controller": "MOTCUBE", "kind": "error", "code": "H11", "description": "ML1 & ML2 signals short circuit to each other", "conditions": "ML1 and ML2 signals must turn ON with a small time difference between them. They are not allowed to turn ON or OFF at the same time. If this happens, this error is raised.", "solution": ["Check the distance of the magnetic switches. It should be 5 cm.", "The distance from the magnetic switch to the door zone ribbon magnet should be 1-2 cm.", "The common of the magnetic switches should be connected to MLO.", "Check the ML1 and ML2 order."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "ML1 ও ML2 signal পরস্পর short circuit", "conditions": "ML1 ও ML2 signal-এর মধ্যে সামান্য সময়ের ব্যবধানে ON হওয়া উচিত। দুটি একই সময়ে ON বা OFF হওয়া গ্রহণযোগ্য নয়। এমন হলে এই error আসে।", "solution": ["Magnetic switch-দের মধ্যে দূরত্ব check করুন। এটি 5 cm হওয়া উচিত।", "Magnetic switch থেকে door zone ribbon magnet-এর দূরত্ব 1-2 cm হওয়া উচিত।", "Magnetic switch-দের common MLO-তে connect থাকতে হবে।", "ML1 ও ML2-এর order check করুন।"], "src": {"d": "afb845be", "c": "a394e9c2", "s": "c213aedd"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h12','MOTCUBE','H12',$j${"id": "motcube-h12", "controller": "MOTCUBE", "kind": "error", "code": "H12", "description": "Door bridging relays SR1 & SR3 don't pick up", "conditions": "Door bridging relays SR1 and SR3 do not pick up.", "solution": ["Check ML1-ML2."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Door bridging relay SR1 ও SR3 pick up করছে না", "conditions": "Door bridging relay SR1 ও SR3 pick up করছে না।", "solution": ["ML1-ML2 check করুন।"], "src": {"d": "39fcad41", "c": "8270ef14", "s": "65206f33"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h13','MOTCUBE','H13',$j${"id": "motcube-h13", "controller": "MOTCUBE", "kind": "error", "code": "H13", "description": "Door bridging relays SR1 or SR3 don't drop", "conditions": "Door bridging relay SR1 or SR3 does not drop.", "solution": ["Check ML1-ML2."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Door bridging relay SR1 বা SR3 drop করছে না", "conditions": "Door bridging relay SR1 বা SR3 drop করছে না।", "solution": ["ML1-ML2 check করুন।"], "src": {"d": "511b9aa3", "c": "9045375a", "s": "65206f33"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h14','MOTCUBE','H14',$j${"id": "motcube-h14", "controller": "MOTCUBE", "kind": "error", "code": "H14", "description": "Door bridging disabled but 140P signal still exists", "conditions": "The 140P signal is still ON after the door bridging is terminated.", "solution": ["Make sure there is no bridge in the safety circuit.", "The connections must be done correctly as shown in the electrical diagram."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Door bridging disabled কিন্তু 140P signal এখনও আছে", "conditions": "Door bridging শেষ হওয়ার পরও 140P signal ON থাকলে এই error আসে।", "solution": ["Safety circuit-এ কোনো bridge নেই তা নিশ্চিত করুন।", "Electrical diagram অনুযায়ী connection সঠিকভাবে করা আছে কিনা দেখুন।"], "src": {"d": "60ca5577", "c": "8a415176", "s": "a900e37c"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h15','MOTCUBE','H15',$j${"id": "motcube-h15", "controller": "MOTCUBE", "kind": "error", "code": "H15", "description": "L1, L2, L3 mains power supply failure", "conditions": "The required voltage could not be read from the L1-L2-L3 inputs.", "solution": ["Measure the phase to phase AC voltages directly on the device.", "If the error is still given although each measurement is correct, the device may be broken down."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "L1, L2, L3 mains power supply failure", "conditions": "L1-L2-L3 input থেকে প্রয়োজনীয় voltage read করা না গেলে এই error আসে।", "solution": ["Device-এর উপরে সরাসরি phase to phase AC voltage measure করুন।", "সব measurement ঠিক থাকার পরও error আসলে device নষ্ট হয়ে থাকতে পারে।"], "src": {"d": "d5f412df", "c": "66886a20", "s": "8a474908"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h16','MOTCUBE','H16',$j${"id": "motcube-h16", "controller": "MOTCUBE", "kind": "error", "code": "H16", "description": "Motor can not spin in evacuation mode", "conditions": "The motor could not be moved during evacuation.", "solution": ["UPS power must be enough.", "Check that the batteries are full."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Evacuation mode-এ motor ঘুরছে না", "conditions": "Evacuation-এর সময় motor নড়াতে না পারলে এই error আসে।", "solution": ["UPS power যথেষ্ট থাকতে হবে।", "Battery full আছে কিনা check করুন।"], "src": {"d": "5ed1d4ce", "c": "aaa17619", "s": "301ca0ec"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h17','MOTCUBE','H17',$j${"id": "motcube-h17", "controller": "MOTCUBE", "kind": "error", "code": "H17", "description": "PTC signal open. Motor over heated", "conditions": "The motor PTC value is above the threshold level.", "solution": ["When parameter \"5.24: PTC TEMPERATURE MONITORING\" is set to \"ENABLED\", check the PTC circuit. In this way, find the component that opens the serial PTC circuit."], "subcodes": [], "fields": [], "category": "", "parameters": ["5.24: PTC TEMPERATURE MONITORING"], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "PTC signal open। Motor over heated", "conditions": "Motor PTC value threshold level-এর উপরে গেলে এই error আসে।", "solution": ["\"5.24: PTC TEMPERATURE MONITORING\" parameter \"ENABLED\" থাকলে PTC circuit check করুন। এভাবে serial PTC circuit যে component open করছে সেটি খুঁজে বের করুন।"], "src": {"d": "8de0be56", "c": "ce398a34", "s": "43149781"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h18','MOTCUBE','H18',$j${"id": "motcube-h18", "controller": "MOTCUBE", "kind": "error", "code": "H18", "description": "DIP switch configuration error", "conditions": "The DIP switch configuration is wrong.", "solution": ["Contact the R&I team when you come across this error."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": true, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "DIP switch configuration error", "conditions": "DIP switch configuration ভুল থাকলে এই error আসে।", "solution": ["এই error আসলে R&I team-এর সাথে যোগাযোগ করুন।"], "src": {"d": "3bdbfe2c", "c": "8258ad62", "s": "62f047a0"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h19','MOTCUBE','H19',$j${"id": "motcube-h19", "controller": "MOTCUBE", "kind": "error", "code": "H19", "description": "Same group ID name used on controllers", "conditions": "The ID numbers of the lifts in the group are entered as the same in the parameter menu.", "solution": ["Select the \"2.21: GROUP IDENTITY\" parameter correctly. If one is selected as Controller-A, the other one must be Controller-B."], "subcodes": [], "fields": [], "category": "", "parameters": ["2.21: GROUP IDENTITY"], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Controller-দের একই Group ID name ব্যবহার করা হয়েছে", "conditions": "Group-এর lift-গুলোর ID number parameter menu-তে একই দেওয়া হলে এই error আসে।", "solution": ["\"2.21: GROUP IDENTITY\" parameter সঠিকভাবে select করুন। একটি Controller-A হলে অন্যটি অবশ্যই Controller-B হতে হবে।"], "src": {"d": "e137e993", "c": "051c7714", "s": "802e77b2"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h21','MOTCUBE','H21',$j${"id": "motcube-h21", "controller": "MOTCUBE", "kind": "error", "code": "H21", "description": "Drive over current error", "conditions": "The current value is over the nominal current value.", "solution": ["The power of the device may have been selected too low for the motor. Check that the capacity of the device is suitable for the motor.", "If this error is raised in open loop, adjust the \"5.17: MOTOR V/F MIDDLE VOLTAGE\" and \"5.19: MOTOR V/F MINIMUM VOLTAGE\" parameters that were calculated during auto tune.", "If it works correctly in open loop but not in closed loop, there may be a problem with the encoder. Check the encoder direction, connections, supply and mounting."], "subcodes": [], "fields": [], "category": "", "parameters": ["5.17: MOTOR V/F MIDDLE VOLTAGE", "5.19: MOTOR V/F MINIMUM VOLTAGE"], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Drive over current error", "conditions": "Current value nominal current value-এর চেয়ে বেশি হলে এই error আসে।", "solution": ["Motor-এর তুলনায় device-এর power কম select করা হয়ে থাকতে পারে। Device-এর capacity motor-এর জন্য উপযুক্ত কিনা check করুন।", "Open loop-এ এই error আসলে auto tune-এর সময় calculate হওয়া \"5.17: MOTOR V/F MIDDLE VOLTAGE\" ও \"5.19: MOTOR V/F MINIMUM VOLTAGE\" parameter ঠিকভাবে adjust করুন।", "Open loop-এ ঠিকভাবে চললেও closed loop-এ না চললে encoder-এ সমস্যা থাকতে পারে। Encoder direction, connection, supply ও mounting check করুন।"], "src": {"d": "e73e63f6", "c": "0fa13125", "s": "d6737118"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h22','MOTCUBE','H22',$j${"id": "motcube-h22", "controller": "MOTCUBE", "kind": "error", "code": "H22", "description": "Service time overflow", "conditions": "If parameter \"2.39: MAINTENANCE TIME CONTROL\" is set to \"ENABLED\", this error is raised after the maintenance time is over. It is a permanent error and the lift will be blocked until the permanent error clearing procedure is applied.", "solution": ["Increase the \"2.40: MAINTENANCE TIME\" parameter.", "Re-arrange the date (dd/mm/yy hh:mm).", "Apply the permanent error clearing procedure (see Permanent Error Clearing section)."], "subcodes": [], "fields": [], "category": "", "parameters": ["2.39: MAINTENANCE TIME CONTROL", "2.40: MAINTENANCE TIME"], "permanent": true, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Service time overflow", "conditions": "\"2.39: MAINTENANCE TIME CONTROL\" parameter \"ENABLED\" থাকলে maintenance time শেষ হওয়ার পর এই error আসে। এটি একটি permanent error; permanent error clearing procedure না করা পর্যন্ত lift block থাকবে।", "solution": ["\"2.40: MAINTENANCE TIME\" parameter-এর মান বাড়ান।", "Date আবার ঠিক করুন (dd/mm/yy hh:mm)।", "Permanent error clearing procedure করুন (Permanent Error Clearing section দেখুন)।"], "src": {"d": "7c4c178d", "c": "b2a21407", "s": "c36eee72"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h23','MOTCUBE','H23',$j${"id": "motcube-h23", "controller": "MOTCUBE", "kind": "error", "code": "H23", "description": "Over speed error", "conditions": "The car speed is above the nominal value.", "solution": ["Check the encoder connections.", "Check the motor parameters.", "The load balance of the lift must be correct. Check it by adding half load inside the car.", "The Speed-PID gain parameters under \"6: PID SETTINGS\" may be adjusted.", "Check the safety circuit. If the safety circuit suddenly turns OFF while the car is moving, the car may speed up."], "subcodes": [], "fields": [], "category": "", "parameters": ["6: PID SETTINGS"], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Over speed error", "conditions": "Car speed nominal value-এর চেয়ে বেশি হলে এই error আসে।", "solution": ["Encoder connection check করুন।", "Motor parameters check করুন।", "Lift-এর load balance সঠিক হতে হবে। Car-এর ভিতরে half load দিয়ে load balance check করুন।", "\"6: PID SETTINGS\"-এর অধীনে Speed-PID gain parameter adjust করতে হতে পারে।", "Safety circuit check করুন। Car চলার সময় হঠাৎ safety circuit OFF হলে car-এর speed বেড়ে যেতে পারে।"], "src": {"d": "6ddc2b54", "c": "0b2374d4", "s": "83257cf3"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h24','MOTCUBE','H24',$j${"id": "motcube-h24", "controller": "MOTCUBE", "kind": "error", "code": "H24", "description": "UCM detection error", "conditions": "While the car is waiting at the floor level with its doors open, it moves out of the door zone magnet. It is a permanent error and the lift will be blocked until the permanent error clearing procedure is applied.", "solution": ["Check the ML1-ML2 magnetic switches.", "Apply the permanent error clearing procedure (see Permanent Error Clearing section)."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": true, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "UCM detection error", "conditions": "Car floor level-এ door open অবস্থায় দাঁড়িয়ে থাকার সময় door zone magnet থেকে বেরিয়ে গেলে এই error আসে। এটি একটি permanent error; permanent error clearing procedure না করা পর্যন্ত lift block থাকবে।", "solution": ["ML1-ML2 magnetic switch check করুন।", "Permanent error clearing procedure করুন (Permanent Error Clearing section দেখুন)।"], "src": {"d": "a484e311", "c": "ef590704", "s": "52606a73"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h25','MOTCUBE','H25',$j${"id": "motcube-h25", "controller": "MOTCUBE", "kind": "error", "code": "H25", "description": "EN signal does not exist", "conditions": "In systems with a synchronous motor, the \"EN\" signal does not turn ON when the motor starts moving.", "solution": ["After the move command, the \"EN\" input on MOTCUBE should be 24V. While stopping, that signal should be cut."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "EN signal নেই", "conditions": "Synchronous motor-যুক্ত system-এ motor চলা শুরু করার সময় \"EN\" signal ON না হলে এই error আসে।", "solution": ["Move command-এর পর MOTCUBE-এর \"EN\" input 24V হওয়া উচিত। থামার সময় signal cut হওয়া উচিত।"], "src": {"d": "a6979661", "c": "fbc9562c", "s": "693c77d4"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h26','MOTCUBE','H26',$j${"id": "motcube-h26", "controller": "MOTCUBE", "kind": "error", "code": "H26", "description": "Brake check back error", "conditions": "When the motor brake is in stop position there is no 24V signal on the input, or there is still a 24V signal when the car starts moving. In synchronous motors, the brake microswitches are monitored over MOTCUBE. When \"5.23: MECHANICAL BRAKE MONITORING\" is \"ENABLED\", there should be a 24V signal on the monitoring input when the car stops, and the signal must be cut while the car is moving. If the same error is repeated 2 times, it becomes a permanent error and the lift will be blocked until the permanent error clearing procedure is applied.", "solution": ["Check the brake microswitch connections.", "Apply the permanent error clearing procedure if it has become permanent (see Permanent Error Clearing section)."], "subcodes": [], "fields": [], "category": "", "parameters": ["5.23: MECHANICAL BRAKE MONITORING"], "permanent": true, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Brake check back error", "conditions": "Motor brake stop position-এ থাকার সময় input-এ 24V signal না থাকলে, অথবা car চলা শুরু করার সময়ও 24V signal থাকলে এই error আসে। Synchronous motor-এ brake microswitch MOTCUBE দিয়ে monitor করা হয়। \"5.23: MECHANICAL BRAKE MONITORING\" \"ENABLED\" থাকলে car থামলে monitoring input-এ 24V থাকতে হবে এবং car চলার সময় signal cut হতে হবে। একই error 2 বার আসলে এটি permanent error হয়ে যায় এবং permanent error clearing procedure না করা পর্যন্ত lift block থাকবে।", "solution": ["Brake microswitch connection check করুন।", "Error permanent হয়ে গেলে permanent error clearing procedure করুন (Permanent Error Clearing section দেখুন)।"], "src": {"d": "5e5e1e0d", "c": "2f0850c9", "s": "3e0f9be8"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h27','MOTCUBE','H27',$j${"id": "motcube-h27", "controller": "MOTCUBE", "kind": "error", "code": "H27", "description": "DC bus voltage exceeded critical level", "conditions": "The DC bus level has reached critical values.", "solution": ["Check the L1, L2, L3 mains supply.", "Check the brake resistor and its connections."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "DC bus voltage critical level ছাড়িয়ে গেছে", "conditions": "DC bus level critical মানে পৌঁছালে এই error আসে।", "solution": ["L1, L2, L3 mains supply check করুন।", "Brake resistor ও তার connection check করুন।"], "src": {"d": "fc0f662e", "c": "ec97901a", "s": "7d779a1c"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h28','MOTCUBE','H28',$j${"id": "motcube-h28", "controller": "MOTCUBE", "kind": "error", "code": "H28", "description": "Door safety circuits are bridged", "conditions": "The \"DOOR OPEN\" relay is activated by the controller when the car stops at the floor level. If the safety circuit (130-140) is not cut after this relay is activated, this error is raised. It is a permanent error and the lift will be blocked until the permanent error clearing procedure is applied.", "solution": ["Check the safety circuit. When the doors are opened, the safety circuit signals should be cut.", "Apply the permanent error clearing procedure (see Permanent Error Clearing section)."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": true, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Door safety circuit bridge করা আছে", "conditions": "Car floor level-এ থামলে controller \"DOOR OPEN\" relay activate করে। এই relay activate হওয়ার পরও safety circuit (130-140) cut না হলে এই error আসে। এটি একটি permanent error; permanent error clearing procedure না করা পর্যন্ত lift block থাকবে।", "solution": ["Safety circuit check করুন। Door খুললে safety circuit signal cut হতে হবে।", "Permanent error clearing procedure করুন (Permanent Error Clearing section দেখুন)।"], "src": {"d": "afaad384", "c": "62a08ceb", "s": "c4e0d824"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h29','MOTCUBE','H29',$j${"id": "motcube-h29", "controller": "MOTCUBE", "kind": "error", "code": "H29", "description": "Low speed error", "conditions": "The car speed is lower than the nominal value. The motor cannot reach the desired speed.", "solution": ["Check the motor parameters and the encoder connections.", "Check the load balance by adding half load inside the car.", "Adjust the speed PID gains under \"6: PID SETTINGS\".", "In asynchronous machines, if there is no error in open loop operation, check the encoder and the ENCI board connections."], "subcodes": [], "fields": [], "category": "", "parameters": ["6: PID SETTINGS"], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Low speed error", "conditions": "Car speed nominal value-এর চেয়ে কম হলে এই error আসে। Motor প্রয়োজনীয় speed-এ পৌঁছাতে পারছে না।", "solution": ["Motor parameters ও encoder connection check করুন।", "Car-এর ভিতরে half load দিয়ে load balance check করুন।", "\"6: PID SETTINGS\"-এর speed PID gain adjust করুন।", "Asynchronous machine-এ open loop operation-এ error না থাকলে encoder ও ENCI board-এর connection check করুন।"], "src": {"d": "daf0d2ca", "c": "f07cf355", "s": "0a4cc7cf"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h30','MOTCUBE','H30',$j${"id": "motcube-h30", "controller": "MOTCUBE", "kind": "error", "code": "H30", "description": "ML1, ML2 signal sequence in reverse", "conditions": "While the car is moving up, ML1 signal is activated first, or while the car is moving down, ML2 signal is activated first. It is a permanent error and the lift will be blocked until the permanent error clearing procedure is applied.", "solution": ["Check the connections of the magnetic switches.", "Apply the permanent error clearing procedure (see Permanent Error Clearing section)."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": true, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "ML1, ML2 signal sequence উল্টো", "conditions": "Car up direction-এ চলার সময় প্রথমে ML1 signal activate হলে, অথবা down direction-এ চলার সময় প্রথমে ML2 signal activate হলে এই error আসে। এটি একটি permanent error; permanent error clearing procedure না করা পর্যন্ত lift block থাকবে।", "solution": ["Magnetic switch-এর connection check করুন।", "Permanent error clearing procedure করুন (Permanent Error Clearing section দেখুন)।"], "src": {"d": "e6b0796c", "c": "148fd700", "s": "0cf60314"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h31','MOTCUBE','H31',$j${"id": "motcube-h31", "controller": "MOTCUBE", "kind": "error", "code": "H31", "description": "Counted door zone number is wrong", "conditions": "During shaft learning, the number of ribbon magnets in the shaft is not the same as the number of floors parameter.", "solution": ["Check the \"2.3: NUMBER OF FLOORS\" parameter.", "Check the number of 30 cm ribbon magnets in the shaft."], "subcodes": [], "fields": [], "category": "", "parameters": ["2.3: NUMBER OF FLOORS"], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Count করা door zone সংখ্যা ভুল", "conditions": "Shaft learning-এর সময় shaft-এর ribbon magnet সংখ্যা number of floors parameter-এর সাথে না মিললে এই error আসে।", "solution": ["\"2.3: NUMBER OF FLOORS\" parameter check করুন।", "Shaft-এ 30 cm ribbon magnet-এর সংখ্যা check করুন।"], "src": {"d": "0bd198fd", "c": "18edb665", "s": "8ee98fcc"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h32','MOTCUBE','H32',$j${"id": "motcube-h32", "controller": "MOTCUBE", "kind": "error", "code": "H32", "description": "817/818 switch activated in wrong direction", "conditions": "While the car is moving up, the 817 signal turns from ON to OFF, or while the car is moving down, the 818 signal turns from ON to OFF.", "solution": ["If the error occurs during up movement, check 817. If it occurs during down movement, check 818.", "There may be a cut or short circuit in the 817, 818 signals.", "There may be a problem with the 817, 818 connection cables.", "Check the motor direction by giving up and down moves in inspection mode."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "817/818 switch ভুল direction-এ activate হয়েছে", "conditions": "Car up direction-এ চলার সময় 817 signal ON থেকে OFF হলে, অথবা down direction-এ চলার সময় 818 signal ON থেকে OFF হলে এই error আসে।", "solution": ["Up যাওয়ার সময় error আসলে 817 check করুন। Down যাওয়ার সময় error আসলে 818 check করুন।", "817, 818 signal-এ cut বা short circuit থাকতে পারে।", "817, 818 connection cable-এ সমস্যা থাকতে পারে।", "Inspection mode-এ up ও down move দিয়ে motor direction check করুন।"], "src": {"d": "b413054f", "c": "c64259ac", "s": "2a5738a6"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h33','MOTCUBE','H33',$j${"id": "motcube-h33", "controller": "MOTCUBE", "kind": "error", "code": "H33", "description": "Shaft encoder direction reverse", "conditions": "The shaft encoder direction is reversed.", "solution": ["Check the shaft encoder connections."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Shaft encoder direction উল্টো", "conditions": "Shaft encoder-এর direction উল্টো হলে এই error আসে।", "solution": ["Shaft encoder connection check করুন।"], "src": {"d": "570cd166", "c": "628642df", "s": "d173d36d"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h34','MOTCUBE','H34',$j${"id": "motcube-h34", "controller": "MOTCUBE", "kind": "error", "code": "H34", "description": "No encoder signal", "conditions": "No encoder signal is detected.", "solution": ["Check the encoder connections."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Encoder signal নেই", "conditions": "Encoder signal পাওয়া না গেলে এই error আসে।", "solution": ["Encoder connection check করুন।"], "src": {"d": "43ea7b4c", "c": "b782c2ec", "s": "1149c575"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h35','MOTCUBE','H35',$j${"id": "motcube-h35", "controller": "MOTCUBE", "kind": "error", "code": "H35", "description": "Speed governor monitoring error", "conditions": "The position of the overspeed governor is monitored over the normally closed contact on MOTCUBE, and an unexpected signal position is detected.", "solution": ["When \"2.10: OSG COIL CONTROL\" is \"ENABLED\", check the \"SGC\" monitor input. While the car is moving there should be no signal here. While standing still there should be 24V."], "subcodes": [], "fields": [], "category": "", "parameters": ["2.10: OSG COIL CONTROL"], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Speed governor monitoring error", "conditions": "Overspeed governor-এর position MOTCUBE-এর normally closed contact দিয়ে monitor করা হয়। অপ্রত্যাশিত signal position পাওয়া গেলে এই error আসে।", "solution": ["\"2.10: OSG COIL CONTROL\" \"ENABLED\" থাকলে \"SGC\" monitor input check করুন। Car চলার সময় এখানে কোনো signal থাকা উচিত নয়। Car দাঁড়িয়ে থাকলে 24V থাকা উচিত।"], "src": {"d": "7a739a1c", "c": "1b2be85e", "s": "1f1becb6"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h36','MOTCUBE','H36',$j${"id": "motcube-h36", "controller": "MOTCUBE", "kind": "error", "code": "H36", "description": "IPM error, transistor short circuit", "conditions": "There may be a short circuit in the power unit inside the motor driver. This error may be given when the car stops suddenly.", "solution": ["The device itself may be faulty. Contact the R&I team if the error persists."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": true, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "IPM error, transistor short circuit", "conditions": "Motor driver-এর ভিতরের power unit-এ short circuit থাকতে পারে। Car হঠাৎ থেমে গেলে এই error আসতে পারে।", "solution": ["Device নিজেই faulty হতে পারে। Error থেকে গেলে R&I team-এর সাথে যোগাযোগ করুন।"], "src": {"d": "1acc777b", "c": "aa5b4555", "s": "39ad4e1a"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h37','MOTCUBE','H37',$j${"id": "motcube-h37", "controller": "MOTCUBE", "kind": "error", "code": "H37", "description": "IPM error, drive supply under voltage", "conditions": "There may be a problem with the IPM supply circuit inside the motor driver.", "solution": ["Contact the R&I team if the error persists."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": true, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "IPM error, drive supply under voltage", "conditions": "Motor driver-এর ভিতরের IPM supply circuit-এ সমস্যা থাকতে পারে।", "solution": ["Error থেকে গেলে R&I team-এর সাথে যোগাযোগ করুন।"], "src": {"d": "c4301204", "c": "c5a21040", "s": "89c845cd"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h38','MOTCUBE','H38',$j${"id": "motcube-h38", "controller": "MOTCUBE", "kind": "error", "code": "H38", "description": "IPM error, IPM over heated", "conditions": "The temperature of the power unit inside the motor driver has increased too much.", "solution": ["Make sure the device is selected correctly according to the motor."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "IPM error, IPM over heated", "conditions": "Motor driver-এর ভিতরের power unit-এর temperature অতিরিক্ত বেড়ে গেলে এই error আসে।", "solution": ["Motor অনুযায়ী device সঠিকভাবে select করা হয়েছে কিনা নিশ্চিত করুন।"], "src": {"d": "3ee65c18", "c": "b522a49c", "s": "5512827c"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h39','MOTCUBE','H39',$j${"id": "motcube-h39", "controller": "MOTCUBE", "kind": "error", "code": "H39", "description": "Motor encoder direction wrong", "conditions": "The encoder connections have been made reversed.", "solution": ["Change the encoder direction from the menu.", "For synchronous machines, when the encoder direction is changed, a new auto tune process must be performed."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Motor encoder direction ভুল", "conditions": "Encoder connection উল্টো করা হলে এই error আসে।", "solution": ["Menu থেকে encoder direction পরিবর্তন করুন।", "Synchronous machine-এ encoder direction পরিবর্তন করলে নতুন করে auto tune করতে হবে।"], "src": {"d": "33db6818", "c": "06857688", "s": "fe2b00d8"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h40','MOTCUBE','H40',$j${"id": "motcube-h40", "controller": "MOTCUBE", "kind": "error", "code": "H40", "description": "Firmware of MDC is invalid", "conditions": "The MDC firmware is invalid.", "solution": ["The MDC firmware needs to be updated."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "MDC-এর firmware invalid", "conditions": "MDC firmware invalid হলে এই error আসে।", "solution": ["MDC firmware update করতে হবে।"], "src": {"d": "22be7ef4", "c": "4a488fc6", "s": "15f75d91"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h41','MOTCUBE','H41',$j${"id": "motcube-h41", "controller": "MOTCUBE", "kind": "error", "code": "H41", "description": "No communication with FX-Cube. Check connection and firmware", "conditions": "The device could not communicate with the car top FX-Cube board.", "solution": ["The FX-Cube firmware needs to be updated.", "During installation, if the inspection box is not connected, make sure the operation mode parameter is selected correctly."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "FX-Cube-এর সাথে communication নেই। Connection ও firmware check করুন", "conditions": "Device car top-এর FX-Cube board-এর সাথে communicate করতে না পারলে এই error আসে।", "solution": ["FX-Cube firmware update করতে হবে।", "Installation-এর সময় inspection box connect না থাকলে operation mode parameter সঠিকভাবে select করুন।"], "src": {"d": "c11c3b50", "c": "6a2c188b", "s": "dac14818"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h42','MOTCUBE','H42',$j${"id": "motcube-h42", "controller": "MOTCUBE", "kind": "error", "code": "H42", "description": "No communication with ENCA encoder board", "conditions": "The device could not communicate with the ENCA board.", "solution": ["Check the cable between ENCA and MOTCUBE.", "The LEDs on the ENCA board should change their position for correct operation.", "There may be a problem with the encoder type selected from the menu, or with the encoder supply."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "ENCA encoder board-এর সাথে communication নেই", "conditions": "Device ENCA board-এর সাথে communicate করতে না পারলে এই error আসে।", "solution": ["ENCA ও MOTCUBE-এর মধ্যে cable check করুন।", "সঠিকভাবে কাজ করার জন্য ENCA board-এর LED-গুলো position পরিবর্তন করতে থাকা উচিত।", "Menu থেকে select করা encoder type অথবা encoder supply-তে সমস্যা থাকতে পারে।"], "src": {"d": "0ac8494d", "c": "867b4a7d", "s": "fd0d7df7"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h43','MOTCUBE','H43',$j${"id": "motcube-h43", "controller": "MOTCUBE", "kind": "error", "code": "H43", "description": "Serial connection error with absolute encoder", "conditions": "There is a serial connection error between the absolute encoder and the encoder board.", "solution": ["Check the connection between the encoder and the encoder board.", "Check the encoder type selected from the menu."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Absolute encoder-এর সাথে serial connection error", "conditions": "Absolute encoder ও encoder board-এর মধ্যে serial connection error হলে এই error আসে।", "solution": ["Encoder ও encoder board-এর মধ্যে connection check করুন।", "Menu থেকে select করা encoder type check করুন।"], "src": {"d": "85e4d0da", "c": "ec644dc8", "s": "ee3459ed"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h44','MOTCUBE','H44',$j${"id": "motcube-h44", "controller": "MOTCUBE", "kind": "error", "code": "H44", "description": "Serial connection error with MDC", "conditions": "The communication cable between MDC and LCB does not exist or is disconnected.", "solution": ["Check the communication cable."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "MDC-এর সাথে serial connection error", "conditions": "MDC ও LCB-এর মধ্যে communication cable না থাকলে বা খুলে গেলে এই error আসে।", "solution": ["Communication cable check করুন।"], "src": {"d": "b69b3e25", "c": "69ab138c", "s": "a871d5a9"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h45','MOTCUBE','H45',$j${"id": "motcube-h45", "controller": "MOTCUBE", "kind": "error", "code": "H45", "description": "L1, L2, L3 phase order failure", "conditions": "When \"2.32: PHASE ORDER CONTROL\" is set to \"ENABLED\", there is a problem with the phase sequence.", "solution": ["Replace the L1 or L3 phase with the L2 phase."], "subcodes": [], "fields": [], "category": "", "parameters": ["2.32: PHASE ORDER CONTROL"], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "L1, L2, L3 phase order failure", "conditions": "\"2.32: PHASE ORDER CONTROL\" \"ENABLED\" থাকলে phase sequence-এ সমস্যা থাকলে এই error আসে।", "solution": ["L1 বা L3 phase-কে L2 phase-এর সাথে বদল করুন।"], "src": {"d": "5f6e213a", "c": "4edd9ae9", "s": "c3b5e54e"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h46','MOTCUBE','H46',$j${"id": "motcube-h46", "controller": "MOTCUBE", "kind": "error", "code": "H46", "description": "Low motor current", "conditions": "The motor current is lower than the nominal value.", "solution": ["Motor terminals may be open circuit. There may be a problem with the motor windings.", "Check the 3-phase windings and earth. The resistance between the phase windings should be the same. There should be high resistance between each phase winding and earth."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Motor current কম", "conditions": "Motor current nominal value-এর চেয়ে কম হলে এই error আসে।", "solution": ["Motor terminal open circuit থাকতে পারে। Motor winding-এ সমস্যা থাকতে পারে।", "3-phase winding ও earth check করুন। Phase winding-দের মধ্যে resistance একই হওয়া উচিত। প্রতিটি phase winding ও earth-এর মধ্যে resistance বেশি হওয়া উচিত।"], "src": {"d": "e747bdcd", "c": "64d2b78a", "s": "d6cfc1db"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h47','MOTCUBE','H47',$j${"id": "motcube-h47", "controller": "MOTCUBE", "kind": "error", "code": "H47", "description": "3-phase detected in mono-phase mode", "conditions": "When \"2.33: MONO PHASE REDUCED SPEED MODE\" is set to \"ENABLED\", a 3-phase supply is connected to the device input.", "solution": ["When a 3-phase input is connected to the device, set this parameter to \"DISABLED\"."], "subcodes": [], "fields": [], "category": "", "parameters": ["2.33: MONO PHASE REDUCED SPEED MODE"], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Mono-phase mode-এ 3-phase detect হয়েছে", "conditions": "\"2.33: MONO PHASE REDUCED SPEED MODE\" \"ENABLED\" থাকা অবস্থায় device input-এ 3-phase connect থাকলে এই error আসে।", "solution": ["Device-এ 3-phase input connect থাকলে এই parameter \"DISABLED\" করুন।"], "src": {"d": "087239cd", "c": "64fda451", "s": "893a3e46"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h48','MOTCUBE','H48',$j${"id": "motcube-h48", "controller": "MOTCUBE", "kind": "error", "code": "H48", "description": "Number of floors of all lifts in the group must be same", "conditions": "The \"2.3: NUMBER OF FLOORS\" parameter of the devices in the group operation is not entered the same.", "solution": ["When the lifts have a different number of floors, set the number of floors parameter the same and adjust the missing floor from top or bottom parameters (\"2.22\" and \"2.23\") correctly."], "subcodes": [], "fields": [], "category": "", "parameters": ["2.3: NUMBER OF FLOORS", "2.22", "2.23"], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Group-এর সব lift-এর floor সংখ্যা একই হতে হবে", "conditions": "Group operation-এর device-গুলোর \"2.3: NUMBER OF FLOORS\" parameter একই না হলে এই error আসে।", "solution": ["Lift-দের floor সংখ্যা আলাদা হলে number of floors parameter একই রাখুন এবং top বা bottom থেকে missing floor-এর parameter (\"2.22\" ও \"2.23\") সঠিকভাবে adjust করুন।"], "src": {"d": "15ef6929", "c": "8102fd9d", "s": "1a5353cf"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h49','MOTCUBE','H49',$j${"id": "motcube-h49", "controller": "MOTCUBE", "kind": "error", "code": "H49", "description": "Door bridging enabled but 140P signal does not exist", "conditions": "Door bridging is enabled but the 140P signal is not present.", "solution": ["Check the SR1 and SR3 relays activated by the ML1 and ML2 signals."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Door bridging enabled কিন্তু 140P signal নেই", "conditions": "Door bridging enabled থাকলেও 140P signal না থাকলে এই error আসে।", "solution": ["ML1 ও ML2 signal দিয়ে activate হওয়া SR1 ও SR3 relay check করুন।"], "src": {"d": "941a0d03", "c": "7f7f8e91", "s": "7105f72f"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h50','MOTCUBE','H50',$j${"id": "motcube-h50", "controller": "MOTCUBE", "kind": "error", "code": "H50", "description": "Earthquake sensor activated", "conditions": "The earthquake input (DEP) is active. It is a permanent error and the lift will be blocked until the permanent error clearing procedure is applied.", "solution": ["Check the assigned DEP input from the programmable inputs.", "Apply the permanent error clearing procedure (see Permanent Error Clearing section)."], "subcodes": [], "fields": [], "category": "", "parameters": ["DEP input (programmable inputs)"], "permanent": true, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Earthquake sensor activated", "conditions": "Earthquake input (DEP) active হলে এই error আসে। এটি একটি permanent error; permanent error clearing procedure না করা পর্যন্ত lift block থাকবে।", "solution": ["Programmable input থেকে assign করা DEP input check করুন।", "Permanent error clearing procedure করুন (Permanent Error Clearing section দেখুন)।"], "src": {"d": "e63047cd", "c": "3b766643", "s": "be018165"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h51','MOTCUBE','H51',$j${"id": "motcube-h51", "controller": "MOTCUBE", "kind": "error", "code": "H51", "description": "Door limit switch fault", "conditions": "When \"7.24: DOOR LIMIT SWITCHES\" is set to \"DOOR OPEN AND CLOSE LIMITS CONNECTED\", the door limit switches do not work correctly.", "solution": ["Set the parameter correctly. If the limit switches are not used, select \"NOT USED\".", "Or make the limit switch connections correctly."], "subcodes": [], "fields": [], "category": "", "parameters": ["7.24: DOOR LIMIT SWITCHES"], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Door limit switch fault", "conditions": "\"7.24: DOOR LIMIT SWITCHES\" \"DOOR OPEN AND CLOSE LIMITS CONNECTED\" থাকা অবস্থায় door limit switch ঠিকভাবে কাজ না করলে এই error আসে।", "solution": ["Parameter সঠিকভাবে set করুন। Limit switch ব্যবহার না করা হলে \"NOT USED\" select করুন।", "অথবা limit switch connection সঠিকভাবে করুন।"], "src": {"d": "a70f44a0", "c": "ca2bad04", "s": "d56abbee"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h52','MOTCUBE','H52',$j${"id": "motcube-h52", "controller": "MOTCUBE", "kind": "error", "code": "H52", "description": "Door contacts bridged", "conditions": "When \"7.25: DOOR CONTACTS BRIDGE CONTROL\" is \"ENABLED\", a test detects short circuit of the door contacts. If an unexpected case occurs during this test, this error is raised.", "solution": ["Check the door type and the safety circuit connections."], "subcodes": [], "fields": [], "category": "", "parameters": ["7.25: DOOR CONTACTS BRIDGE CONTROL"], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Door contacts bridge করা আছে", "conditions": "\"7.25: DOOR CONTACTS BRIDGE CONTROL\" \"ENABLED\" থাকলে door contact-এর short circuit detect করার একটি test হয়। এই test-এর সময় অপ্রত্যাশিত কিছু ঘটলে এই error আসে।", "solution": ["Door type ও safety circuit connection check করুন।"], "src": {"d": "d458fe01", "c": "0f30a957", "s": "3ca2264a"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h53','MOTCUBE','H53',$j${"id": "motcube-h53", "controller": "MOTCUBE", "kind": "error", "code": "H53", "description": "Bypass socket connection wrong", "conditions": "When \"7.26: DOOR BY-PASSING SOCKET\" is \"ENABLED\", the bypass socket on the LCB board has a problem, the cable is connected to a wrong place, or no cable is connected.", "solution": ["Normally there should be a bridge cable only in the socket labelled NORMAL. The other sockets should be empty."], "subcodes": [], "fields": [], "category": "", "parameters": ["7.26: DOOR BY-PASSING SOCKET"], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Bypass socket connection ভুল", "conditions": "\"7.26: DOOR BY-PASSING SOCKET\" \"ENABLED\" থাকলে LCB board-এর bypass socket-এ সমস্যা থাকলে, cable ভুল জায়গায় লাগানো থাকলে, বা কোনো cable না থাকলে এই error আসে।", "solution": ["স্বাভাবিক অবস্থায় শুধু NORMAL লেখা socket-এ bridge cable থাকবে। বাকি socket ফাঁকা থাকবে।"], "src": {"d": "c5d0d2af", "c": "7bc284ff", "s": "ddb67d97"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h54','MOTCUBE','H54',$j${"id": "motcube-h54", "controller": "MOTCUBE", "kind": "error", "code": "H54", "description": "Maximum allowed speed exceeded with bridged door", "conditions": "During door pre-opening or re-leveling, the car speed is more than the value entered in parameter \"7.27: BRIDGED DOOR ALLOWED MAX SPEED\".", "solution": ["Check the \"7.27: BRIDGED DOOR ALLOWED MAX SPEED\" parameter and the car speed during pre-opening or re-leveling."], "subcodes": [], "fields": [], "category": "", "parameters": ["7.27: BRIDGED DOOR ALLOWED MAX SPEED"], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Bridged door অবস্থায় সর্বোচ্চ অনুমোদিত speed ছাড়িয়ে গেছে", "conditions": "Door pre-opening বা re-leveling-এর সময় car speed \"7.27: BRIDGED DOOR ALLOWED MAX SPEED\" parameter-এ দেওয়া মানের চেয়ে বেশি হলে এই error আসে।", "solution": ["\"7.27: BRIDGED DOOR ALLOWED MAX SPEED\" parameter এবং pre-opening বা re-leveling-এর সময় car speed check করুন।"], "src": {"d": "08936828", "c": "f0281ee4", "s": "a24e9ddc"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h55','MOTCUBE','H55',$j${"id": "motcube-h55", "controller": "MOTCUBE", "kind": "error", "code": "H55", "description": "Reached direction changing limit", "conditions": "If parameter \"2.41: DIRECTION CHANGING LIMIT\" is set to a value other than 0, this error is raised when the number of direction changes reaches the entered value. It is a permanent error.", "solution": ["Enter the statistics screen and reset the number of direction changes by pressing the ENTER key on \"1. DIRECTION CHANGING NUMBER\".", "After resetting the statistics, also clear the permanent error (see Permanent Error Clearing section)."], "subcodes": [], "fields": [], "category": "", "parameters": ["2.41: DIRECTION CHANGING LIMIT"], "permanent": true, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Direction changing limit-এ পৌঁছেছে", "conditions": "\"2.41: DIRECTION CHANGING LIMIT\" parameter 0 ছাড়া অন্য মানে set থাকলে, direction change-এর সংখ্যা সেই মানে পৌঁছালে এই error আসে। এটি একটি permanent error।", "solution": ["Statistics screen-এ গিয়ে \"1. DIRECTION CHANGING NUMBER\"-এ ENTER key চেপে direction change-এর সংখ্যা reset করুন।", "Statistics reset করার পর permanent error-ও clear করুন (Permanent Error Clearing section দেখুন)।"], "src": {"d": "d9bd174a", "c": "18ccec62", "s": "dcea289b"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h56','MOTCUBE','H56',$j${"id": "motcube-h56", "controller": "MOTCUBE", "kind": "error", "code": "H56", "description": "Shaft input detected", "conditions": "If parameter \"2.30: SHAFT INPUT PROTECTION\" is \"ENABLED\", this error is raised when the \"(SPRn) SHAFT ENTRY PROTECTION FLOOR-n\" signal is received from a floor other than the floor where the car is located. It is a permanent error.", "solution": ["Clear the permanent error (see Permanent Error Clearing section)."], "subcodes": [], "fields": [], "category": "", "parameters": ["2.30: SHAFT INPUT PROTECTION"], "permanent": true, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Shaft input detect হয়েছে", "conditions": "\"2.30: SHAFT INPUT PROTECTION\" parameter \"ENABLED\" থাকলে, car যে floor-এ আছে সেটি ছাড়া অন্য কোনো floor থেকে \"(SPRn) SHAFT ENTRY PROTECTION FLOOR-n\" signal এলে এই error আসে। এটি একটি permanent error।", "solution": ["Permanent error clear করুন (Permanent Error Clearing section দেখুন)।"], "src": {"d": "f10380f7", "c": "b7deedf7", "s": "c00430f9"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h57','MOTCUBE','H57',$j${"id": "motcube-h57", "controller": "MOTCUBE", "kind": "error", "code": "H57", "description": "120 was OFF during movement", "conditions": "The 120 signal is OFF while the car is moving.", "solution": ["Check the safety circuit and the 120 signal."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Movement-এর সময় 120 OFF হয়েছে", "conditions": "Car চলার সময় 120 signal OFF হলে এই error আসে।", "solution": ["Safety circuit ও 120 signal check করুন।"], "src": {"d": "5fea8f1a", "c": "e9dd3f3a", "s": "df201bfc"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h58','MOTCUBE','H58',$j${"id": "motcube-h58", "controller": "MOTCUBE", "kind": "error", "code": "H58", "description": "130 was OFF during movement", "conditions": "The 130 signal is OFF while the car is moving.", "solution": ["Check the safety circuit and the 130 signal."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Movement-এর সময় 130 OFF হয়েছে", "conditions": "Car চলার সময় 130 signal OFF হলে এই error আসে।", "solution": ["Safety circuit ও 130 signal check করুন।"], "src": {"d": "8ea06421", "c": "6c45e347", "s": "47e3b5c9"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h59','MOTCUBE','H59',$j${"id": "motcube-h59", "controller": "MOTCUBE", "kind": "error", "code": "H59", "description": "135 was OFF during movement", "conditions": "The 135 signal is OFF while the car is moving (except for door pre-opening and re-leveling).", "solution": ["Check the safety circuit and the 135 signal."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Movement-এর সময় 135 OFF হয়েছে", "conditions": "Car চলার সময় 135 signal OFF হলে এই error আসে (door pre-opening ও re-leveling ছাড়া)।", "solution": ["Safety circuit ও 135 signal check করুন।"], "src": {"d": "a074ec98", "c": "92d75718", "s": "bdd8d066"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h60','MOTCUBE','H60',$j${"id": "motcube-h60", "controller": "MOTCUBE", "kind": "error", "code": "H60", "description": "140 was OFF during movement", "conditions": "The 140 signal is OFF while the car is moving (except for door pre-opening and re-leveling).", "solution": ["Check the safety circuit and the 140 signal."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Movement-এর সময় 140 OFF হয়েছে", "conditions": "Car চলার সময় 140 signal OFF হলে এই error আসে (door pre-opening ও re-leveling ছাড়া)।", "solution": ["Safety circuit ও 140 signal check করুন।"], "src": {"d": "fe064998", "c": "077cdda8", "s": "214e4c02"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h61','MOTCUBE','H61',$j${"id": "motcube-h61", "controller": "MOTCUBE", "kind": "error", "code": "H61", "description": "140P was OFF during movement", "conditions": "The 140P signal is OFF while the car is moving.", "solution": ["Check the safety circuit and the 140P signal."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": false, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Movement-এর সময় 140P OFF হয়েছে", "conditions": "Car চলার সময় 140P signal OFF হলে এই error আসে।", "solution": ["Safety circuit ও 140P signal check করুন।"], "src": {"d": "d0aaa218", "c": "07cb9f66", "s": "1de00930"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-h62','MOTCUBE','H62',$j${"id": "motcube-h62", "controller": "MOTCUBE", "kind": "error", "code": "H62", "description": "Installation activation required", "conditions": "Installation activation of MOTCUBE must be performed one time. If it is not done, the lift gives this error after 1 hour of normal operation. This error does not occur in inspection or recall mode.", "solution": ["Perform the installation activation of MOTCUBE. If you do not know the procedure, contact the R&I team."], "subcodes": [], "fields": [], "category": "", "parameters": [], "permanent": false, "contactRni": true, "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1, "bn": {"description": "Installation activation প্রয়োজন", "conditions": "MOTCUBE-এর installation activation একবার করতে হয়। না করলে normal operation-এ 1 ঘণ্টা পর lift এই error দেয়। Inspection বা recall mode-এ এই error আসে না।", "solution": ["MOTCUBE-এর installation activation করুন। Procedure জানা না থাকলে R&I team-এর সাথে যোগাযোগ করুন।"], "src": {"d": "5311f086", "c": "ed3645dd", "s": "bc245eab"}}}$j$::jsonb,1) on conflict do nothing;
insert into public.wlf_troubleshooting(id,controller,option_key,content,revision) values('motcube-permanent-error-clearing','MOTCUBE','procedure:permanenterrorclearing',$j${"id": "motcube-permanent-error-clearing", "controller": "MOTCUBE", "kind": "procedure", "code": "", "description": "How to clear a permanent error (H22, H24, H26, H28, H30, H50, H55, H56) / Permanent error মোছার নিয়ম", "conditions": "", "solution": [], "subcodes": [], "fields": [{"label": "Step 1 / ধাপ 1", "text": "At the main menu (while waiting), press the \"RIGHT\" button until the \"PERMANENT ERROR\" screen appears.\nMain menu-তে (waiting অবস্থায়) \"RIGHT\" button চাপতে থাকুন যতক্ষণ \"PERMANENT ERROR\" screen না আসে।"}, {"label": "Step 2 / ধাপ 2", "text": "Press the \"UP\" and \"DOWN\" buttons together to clear the permanent error.\n\"UP\" ও \"DOWN\" button একসাথে চেপে permanent error clear করুন।"}, {"label": "Step 3 / ধাপ 3", "text": "Switch the lift to inspection mode and then back to normal mode using the inspection hand terminal.\nInspection hand terminal দিয়ে lift-কে inspection mode-এ নিয়ে আবার normal mode-এ ফিরিয়ে আনুন।"}], "category": "Permanent Error Clearing", "source": {"manual": "MOTCUBE Quick Installation Guide", "version": "V1.02 / July 2020", "file": "MOTCUBE_error_codes_en.json", "pages": []}, "revision": 1}$j$::jsonb,1) on conflict do nothing;

notify pgrst, 'reload schema';
commit;

-- ---------------------------------------------------------------- check
select
  (select count(*) from public.wlf_troubleshooting where controller='MOTCUBE' and not deleted and content->>'kind'='error')>=1 as motcube_codes_ready,
  (select count(*) from public.wlf_troubleshooting where controller='MOTCUBE' and not deleted and content->>'kind'='error') as motcube_error_codes,
  (select count(*) from jsonb_array_elements(wlf_private.catalog()) x where x->>'key'='tb:MOTCUBE:error')=1 as motcube_permission_ready,
  exists(select 1 from information_schema.columns where table_schema='wlf_private' and table_name='damage_demands' and column_name='claim_ref') as supplier_reference_ready,
  to_regprocedure('wlf_private.rpc_before_v255(text,jsonb)') is not null as v255_ready;
